import{_ as t,o,c as a,a3 as i}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Payment Gateways — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payment Gateways — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/payment-gateways"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payment Gateways — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/payment-gateways"}]]},"headers":[],"relativePath":"deployment/payment-gateways.md","filePath":"deployment/payment-gateways.md","lastUpdated":1794259478000}'),n={name:"deployment/payment-gateways.md"};function s(c,e,r,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="payment-gateways-—-production-guide" tabindex="-1">Payment Gateways — Production Guide <a class="header-anchor" href="#payment-gateways-—-production-guide" aria-label="Permalink to &quot;Payment Gateways — Production Guide&quot;">​</a></h1><h2 id="checklist-stripe" tabindex="-1">Checklist (Stripe) <a class="header-anchor" href="#checklist-stripe" aria-label="Permalink to &quot;Checklist (Stripe)&quot;">​</a></h2><ol><li>Seed gateways: <code>PaymentGatewaySeeder</code> (manual + stripe + creem + kelviq + lemonsqueezy).</li><li>In Central UI, configure Stripe <strong>live</strong> credentials (or set encrypted config via API).</li><li>Set Stripe as default only after a successful <strong>Test connection</strong>.</li><li>Register webhooks in the Stripe Dashboard: <ul><li>Prefer <code>https://{APP_URL}/stripe/webhook</code> for Cashier subscription mirror + Billing Engine</li><li>Or <code>https://{APP_URL}/webhooks/gateways/stripe</code> for Billing Engine only</li></ul></li><li>Store the webhook signing secret in gateway config (<code>webhook_secret</code>) and/or <code>STRIPE_WEBHOOK_SECRET</code> for Cashier middleware.</li><li>Confirm CSRF exclusions remain for <code>stripe/*</code> and <code>webhooks/gateways/*</code>.</li><li>Monitor <strong>webhook status</strong> and <code>webhook_logs</code> after go-live.</li></ol><h2 id="checklist-kelviq" tabindex="-1">Checklist (Kelviq) <a class="header-anchor" href="#checklist-kelviq" aria-label="Permalink to &quot;Checklist (Kelviq)&quot;">​</a></h2><ol><li>Complete Kelviq business verification and payouts for the collecting legal entity.</li><li>Publish production plans; map live plan identifiers under <strong>Billing → Payment Gateways → Product mapping</strong>.</li><li>Set hosting secrets: production Server API key + webhook secret; <code>KELVIQ_ENV=production</code>; gateway mode <strong>live</strong>.</li><li>Register <code>https://api.elosync.com/webhooks/gateways/kelviq</code> for <code>checkout.completed</code>, <code>invoice.payment_failed</code>, <code>subscription.created</code>, <code>subscription.updated</code>, <code>subscription.plan_changed</code>, <code>subscription.cancelled</code>.</li><li>Sandbox E2E purchase must pass before setting Kelviq as Central default.</li><li>See <a href="/developer-guide/kelviq">Kelviq gateway</a> for sandbox ops and event mapping.</li></ol><h2 id="checklist-lemon-squeezy" tabindex="-1">Checklist (Lemon Squeezy) <a class="header-anchor" href="#checklist-lemon-squeezy" aria-label="Permalink to &quot;Checklist (Lemon Squeezy)&quot;">​</a></h2><ol><li>Complete Lemon Squeezy store approval / payouts for live charges.</li><li>Create live subscription products + monthly/yearly variants; map <strong>Variant IDs</strong> under <strong>Billing → Payment Gateways → Product mapping</strong> (no API catalog sync).</li><li>Set hosting secrets: live API key + store id + webhook secret; <code>LEMONSQUEEZY_ENV=live</code>; gateway mode <strong>live</strong>; <code>LEMONSQUEEZY_TEST_MODE=false</code>.</li><li>Register <code>https://api.elosync.com/webhooks/gateways/lemonsqueezy</code> (<code>X-Signature</code>) for <code>subscription_*</code> and <code>subscription_payment_*</code> events.</li><li>Sandbox E2E purchase must pass before setting Lemon Squeezy as Central default.</li><li>See <a href="/developer-guide/lemonsqueezy">Lemon Squeezy gateway</a> for sandbox ops and event mapping.</li></ol><h2 id="environment-fallbacks" tabindex="-1">Environment fallbacks <a class="header-anchor" href="#environment-fallbacks" aria-label="Permalink to &quot;Environment fallbacks&quot;">​</a></h2><p><code>StripeGateway</code> prefers encrypted <code>payment_gateways.config.secret_key</code>. If absent, it falls back to Cashier env (<code>STRIPE_SECRET</code>). <code>KelviqGateway</code> prefers the same encrypted config keys, falling back to <code>KELVIQ_SERVER_API_KEY</code> / <code>KELVIQ_WEBHOOK_SECRET</code>. <code>LemonSqueezyGateway</code> falls back to <code>LEMONSQUEEZY_API_KEY</code> / <code>LEMONSQUEEZY_WEBHOOK_SECRET</code> / <code>LEMONSQUEEZY_STORE_ID</code>. Production should treat DB-encrypted credentials as source of truth so credentials can rotate without redeploying env.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>Never log secret values — only changed key names.</li><li>Never return secrets from API resources.</li><li>Prefer sandbox mode until connection tests pass.</li><li>Rotate webhook secrets after any suspected leak; update both Stripe Dashboard and gateway config.</li></ul><h2 id="ops-signals" tabindex="-1">Ops signals <a class="header-anchor" href="#ops-signals" aria-label="Permalink to &quot;Ops signals&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Signal</th><th>Source</th></tr></thead><tbody><tr><td><code>payment_gateways.webhook_status</code></td><td><code>ok</code> / <code>failing</code> / <code>unknown</code></td></tr><tr><td><code>webhook_last_received_at</code></td><td>Last successful ingress</td></tr><tr><td><code>gateway_logs</code></td><td>Config/mode/test events</td></tr><tr><td><code>webhook_logs</code></td><td>Per-event processing result + timing</td></tr></tbody></table>',13)])])}const y=t(n,[["render",s]]);export{u as __pageData,y as default};
